+            doc.identifier(),
+            doc.traderAssignedId(),
+            doc.notificationStatusCode(),
+            doc.versionId(),
+            doc.issueDateTime(),
+            commonMapper.mapAuthentication(doc.firstSignatoryAuthentication()),
+            mapList(doc.referenceDocument(), commonMapper::mapReferencedDocument)
+        );
+    }
